def comb_sort(nums):
    gap = len(nums)
    shrink = True

    while gap != 1 or shrink:
        gap = max(1, gap // 1.2)
        shrink = False

        for i in range(len(nums) - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                shrink = True
    return nums
